={{ "Classify the following LinkedIn post according to the rules given.

LinkedIn Post:
" + ($json.text || $json.postText || $json.content || JSON.stringify($json)) }}

parameters.jsCode:
// Clean up markdown fences from Gemini
const raw = $json.text || $json.output || $json.content || '';
const clean = raw.replace(/```json|```/gi, '').trim();

let verdict = "not_relevant";
try {
    const parsed = JSON.parse(clean);
    verdict = parsed.verdict;
} catch(e) {}

return {
    json: {
        verdict: verdict,
        originalPost: $('Loop Over Items').item.json.text || $('Loop Over Items').item.json.postText || $('Loop Over Items').item.json.content || '',
        postUrl: $('Loop Over Items').item.json.url || $('Loop Over Items').item.json.postUrl || '',
        creator: $('Loop Over Items').item.json.authorName || $('Loop Over Items').item.json.author || '',
        likes: $('Loop Over Items').item.json.likesCount || $('Loop Over Items').item.json.likes || 0,
        comments: $('Loop Over Items').item.json.commentsCount || $('Loop Over Items').item.json.comments || 0,
        postDate: $('Loop Over Items').item.json.postedAt || $('Loop Over Items').item.json.date || ''
    }
};
